    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read::lookup;

struct Node;

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let CustomerQuery {
            intent,
            entities: _,
            question,
        } = query.query;

        // requires len(query.question) <= 512 holds of the input, and we pass
        // `question` through unchanged, so `ensures len(question) <= 512` holds.
        //
        // Read-only lookup against the single granted handle
        // (DBHandle<'knowledge-base', read>). This is the only authority this
        // node has, and the only I/O it performs.
        let mut knowledge = lookup(&question);

        // ensures present(knowledge): guarantee a non-empty payload even when the
        // store returns nothing for this question.
        if knowledge.is_empty() {
            knowledge.push(String::new());
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
