        let mut knowledge = lookup(&question);

        // ensures present(knowledge): never return an empty list.
        if knowledge.is_empty() {
            knowledge.push(String::new());
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

